  // 2) Check what energy to ignore its amount //  ** Affects check 5 and 6  // > CustomCode.answerAssistants:47
  ///////////////////////////////////////////////  returns a list ID to ignore  // > CustomCode.answerAssistants:48
  function energyToIgnore(C,E,G,I,K,N){  // > CustomCode.answerAssistants:49
    let checkLst = [C,E,G,I,K,N];  // lst contains T/F  // > CustomCode.answerAssistants:50
    let indexLst = [];  // > CustomCode.answerAssistants:51
    for (let i=0; i < checkLst.length; i++){  // > CustomCode.answerAssistants:52
      if (checkLst[i]==true){indexLst.push(i);}  // > CustomCode.answerAssistants:53
      }  // > CustomCode.answerAssistants:54
    return indexLst  // > CustomCode.answerAssistants:55
    }  // > CustomCode.answerAssistants:56
  function zeroExceptEnergy(C,E,G,I,K,N){  // Scenario 1: (false, false, false, false, TRUE, false)  // > CustomCode.answerAssistants:57
    // check which index gives false from the argument --> index to check //  // > CustomCode.answerAssistants:58
    let indexLst = [];  // > CustomCode.answerAssistants:59
    if (C==false){indexLst.push(0)}  // > CustomCode.answerAssistants:60
    if (E==false){indexLst.push(1)}  // > CustomCode.answerAssistants:61
    if (G==false){indexLst.push(2)}  // > CustomCode.answerAssistants:62
    if (I==false){indexLst.push(3)}  // > CustomCode.answerAssistants:63
    if (K==false){indexLst.push(4)}  // > CustomCode.answerAssistants:64
    if (N==false){indexLst.push(5)}  // > CustomCode.answerAssistants:65
    // checking process: //  // > CustomCode.answerAssistants:66
    for (let i=0; i< iniTotalEnergy.length; i++){  // > CustomCode.answerAssistants:67
      // Skip any energy that is true, so to check for 0 //  // > CustomCode.answerAssistants:68
      for (let j=0; j < indexLst.length; j++){  // > CustomCode.answerAssistants:69
        if ( (indexLst[j] ==i) && ( (iniTotalEnergy[i] !=0)||(finTotalEnergy[i] !=0)  ) ){  // > CustomCode.answerAssistants:70
          return false  // > CustomCode.answerAssistants:71
          }  // > CustomCode.answerAssistants:72
        }  // > CustomCode.answerAssistants:73
      }  // > CustomCode.answerAssistants:74
    return true  // > CustomCode.answerAssistants:75
    }  // > CustomCode.answerAssistants:76
      // > CustomCode.answerAssistants:77
  /////////////////////////////////////////////////  // > CustomCode.answerAssistants:78
  // 3) Check what energy is being transfered IN // (O)  // > CustomCode.answerAssistants:79
  /////////////////////////////////////////////////  // > CustomCode.answerAssistants:80
  function check3assistant(){    // > CustomCode.answerAssistants:81
    // check3b is true, means confirm 2 types of energy are transferred  // > CustomCode.answerAssistants:82
    if (check3b){  // > CustomCode.answerAssistants:83
      // → if 2, need check IN correct, followed by IN2 and vice versa.   // > CustomCode.answerAssistants:84
      if (check3a && (EtransIN >= 0 && EtransIN2 >= 0) ){  // > CustomCode.answerAssistants:85
        if ((EtransIN > 0 && updateTransIN == 0) || (EtransIN2 > 0 && updateTransIN2 == 0)) {  // > CustomCode.answerAssistants:86
            hint = "Unspecified energy cannot have a value of more than 0.";  // > CustomCode.answerAssistants:87
            return false  // > CustomCode.answerAssistants:88
        }  // > CustomCode.answerAssistants:89
        if ((updateTransIN == 0 && check3aEnergy == "") ||  // > CustomCode.answerAssistants:90
            (updateTransIN == 1 && check3aEnergy == "through propagation of waves") ||   // > CustomCode.answerAssistants:91
            (updateTransIN == 2 && check3aEnergy == "mechanically") ||   // > CustomCode.answerAssistants:92
            (updateTransIN == 3 && check3aEnergy == "through heating") ||   // > CustomCode.answerAssistants:93
            (updateTransIN == 4 && check3aEnergy == "electrically") ||   // > CustomCode.answerAssistants:94
            (updateTransIN == 5 && check3aEnergy == "chemically") ){  // > CustomCode.answerAssistants:95
          if (updateTransIN2 == 0 && check3bEnergy == ""){return true}  // > CustomCode.answerAssistants:96
          else if (updateTransIN2 == 1 && check3bEnergy == "through propagation of waves"){return true}  // > CustomCode.answerAssistants:97
          else if (updateTransIN2 == 2 && check3bEnergy == "mechanically"){return true}  // > CustomCode.answerAssistants:98
          else if (updateTransIN2 == 3 && check3bEnergy == "through heating"){return true}  // > CustomCode.answerAssistants:99
          else if (updateTransIN2 == 4 && check3bEnergy == "electrically"){return true}  // > CustomCode.answerAssistants:100
          else if (updateTransIN2 == 5 && check3bEnergy == "chemically"){return true}  // > CustomCode.answerAssistants:101
          else{  // > CustomCode.answerAssistants:102
            hint = "There should be some energy transferred into\nthe system "+check3bEnergy+" due to \n"+check3bReason;  // > CustomCode.answerAssistants:103
            return false  // > CustomCode.answerAssistants:104
            }  // > CustomCode.answerAssistants:105
          }  // > CustomCode.answerAssistants:106
        else if ((updateTransIN2 == 0 && check3aEnergy == "") ||  // > CustomCode.answerAssistants:107
            (updateTransIN2 == 1 && check3aEnergy == "through propagation of waves") ||   // > CustomCode.answerAssistants:108
            (updateTransIN2 == 2 && check3aEnergy == "mechanically") ||   // > CustomCode.answerAssistants:109
            (updateTransIN2 == 3 && check3aEnergy == "through heating") ||   // > CustomCode.answerAssistants:110
            (updateTransIN2 == 4 && check3aEnergy == "electrically") ||  // > CustomCode.answerAssistants:111
            (updateTransIN2 == 5 && check3aEnergy == "chemically") ){  // > CustomCode.answerAssistants:112
          if (updateTransIN == 0 && check3bEnergy == ""){return true}  // > CustomCode.answerAssistants:113
          else if (updateTransIN == 1 && check3bEnergy == "through propagation of waves"){return true}  // > CustomCode.answerAssistants:114
          else if (updateTransIN == 2 && check3bEnergy == "mechanically"){return true}  // > CustomCode.answerAssistants:115
          else if (updateTransIN == 3 && check3bEnergy == "through heating"){return true}  // > CustomCode.answerAssistants:116
          else if (updateTransIN == 4 && check3bEnergy == "electrically"){return true}  // > CustomCode.answerAssistants:117
          else if (updateTransIN == 5 && check3bEnergy == "chemically"){return true}  // > CustomCode.answerAssistants:118
          else{  // > CustomCode.answerAssistants:119
            hint = "There should be some energy transferred\ninto the system "+check3bEnergy+" due to \n"+check3bReason;  // > CustomCode.answerAssistants:120
            return false  // > CustomCode.answerAssistants:121
            }  // > CustomCode.answerAssistants:122
          }  // > CustomCode.answerAssistants:123
        else{  // > CustomCode.answerAssistants:124
          hint = "There should be some energy transferred\ninto the system "+check3aEnergy+" due to \n"+check3aReason;  // > CustomCode.answerAssistants:125
          return false  // > CustomCode.answerAssistants:126
          }  // > CustomCode.answerAssistants:127
        }  // > CustomCode.answerAssistants:128
      else{  // > CustomCode.answerAssistants:129
        hint = "There should have some energy\ntransferred into the system\n"+check3aEnergy+" and "+check3bEnergy+".";  // > CustomCode.answerAssistants:130
        }  // > CustomCode.answerAssistants:131
      }  // > CustomCode.answerAssistants:132
    // check3a is true, means there can be 1 or 2 types of energy transferred → no need check for 2 cuz check3b wldve been T  // > CustomCode.answerAssistants:133
    else if (check3a){  // > CustomCode.answerAssistants:134
      if ((EtransIN > 0 && updateTransIN == 0)) {  // > CustomCode.answerAssistants:135
          hint = "Unspecified energy cannot have a value of more than 0.";  // > CustomCode.answerAssistants:136
          return false  // > CustomCode.answerAssistants:137
       }  // > CustomCode.answerAssistants:138
      // → if only 1, just need to check whether the IN or IN2 is correctly identified  // > CustomCode.answerAssistants:139
      if (EtransIN >= 0 && EtransIN2 == 0){  // > CustomCode.answerAssistants:140
        if (updateTransIN == 0 && check3aEnergy == ""){return true}  // > CustomCode.answerAssistants:141
        if (updateTransIN == 1 && check3aEnergy == "through propagation of waves"){return true}  // > CustomCode.answerAssistants:142
        if (updateTransIN == 2 && check3aEnergy == "mechanically"){return true}  // > CustomCode.answerAssistants:143
        if (updateTransIN == 3 && check3aEnergy == "through heating"){return true}  // > CustomCode.answerAssistants:144
        if (updateTransIN == 4 && check3aEnergy == "electrically"){return true}  // > CustomCode.answerAssistants:145
        if (updateTransIN == 5 && check3aEnergy == "chemically"){return true}  // > CustomCode.answerAssistants:146
        }  // > CustomCode.answerAssistants:147
      else if (EtransIN == 0 && EtransIN2 >= 0){  // > CustomCode.answerAssistants:148
        if (updateTransIN2 == 0 && check3aEnergy == ""){return true}  // > CustomCode.answerAssistants:149
        if (updateTransIN2 == 1 && check3aEnergy == "through propagation of waves"){return true}  // > CustomCode.answerAssistants:150
        if (updateTransIN2 == 2 && check3aEnergy == "mechanically"){return true}  // > CustomCode.answerAssistants:151
        if (updateTransIN2 == 3 && check3aEnergy == "through heating"){return true}  // > CustomCode.answerAssistants:152
        if (updateTransIN2 == 4 && check3aEnergy == "electrically"){return true}  // > CustomCode.answerAssistants:153
        if (updateTransIN2 == 5 && check3aEnergy == "chemically"){return true}  // > CustomCode.answerAssistants:154
        }  // > CustomCode.answerAssistants:155
      else if (EtransIN >= 0 && EtransIN2 >= 0){  // > CustomCode.answerAssistants:156
        if (updateTransIN == 0 && updateTransIN2 == 0 && check3aEnergy == ""){return true}  // > CustomCode.answerAssistants:157
        if (updateTransIN == 1 && updateTransIN2 == 1 && check3aEnergy == "through propagation of waves"){return true}  // > CustomCode.answerAssistants:158
        if (updateTransIN == 2 && updateTransIN2 == 2 && check3aEnergy == "mechanically"){return true}  // > CustomCode.answerAssistants:159
        if (updateTransIN == 3 && updateTransIN2 == 3 && check3aEnergy == "through heating"){return true}  // > CustomCode.answerAssistants:160
        if (updateTransIN == 4 && updateTransIN2 == 4 && check3aEnergy == "electrically"){return true}  // > CustomCode.answerAssistants:161
        if (updateTransIN == 5 && updateTransIN2 == 5 && check3aEnergy == "chemically"){return true}  // > CustomCode.answerAssistants:162
        hint = "There should only be some energy transferred\ninto the system "+ check3aEnergy+".";  // > CustomCode.answerAssistants:163
        return false  // > CustomCode.answerAssistants:164
        }  // > CustomCode.answerAssistants:165
      /*  // > CustomCode.answerAssistants:166
      else{  // > CustomCode.answerAssistants:167
        hint = "There should be some energy transferred\ninto the system "+check3aEnergy+" due to \n"+check3aReason;  // > CustomCode.answerAssistants:168
        return false  // > CustomCode.answerAssistants:169
        }  // > CustomCode.answerAssistants:170
      */  // > CustomCode.answerAssistants:171
      hint = "There should be some energy transferred\ninto the system "+check3aEnergy+" due to \n"+check3aReason;  // > CustomCode.answerAssistants:172
      return false  // > CustomCode.answerAssistants:173
      }  // > CustomCode.answerAssistants:174
    else if (check3a ==false && check3b ==false){  // > CustomCode.answerAssistants:175
      if (EtransIN ==0 && EtransIN2 ==0){return true}  // > CustomCode.answerAssistants:176
      else{  // > CustomCode.answerAssistants:177
        hint = "The energy transferred into\nthe system should be zero.";  // > CustomCode.answerAssistants:178
        return false  // > CustomCode.answerAssistants:179
        }  // > CustomCode.answerAssistants:180
      }  // > CustomCode.answerAssistants:181
    else{  // > CustomCode.answerAssistants:182
      debuggg="smth wrong at check3 :( ";  // > CustomCode.answerAssistants:183
      return true  // > CustomCode.answerAssistants:184
      }  // > CustomCode.answerAssistants:185
    }  // > CustomCode.answerAssistants:186
