  //////////////////////////////////////////////////////////  // > CustomCode.answerAssistants:188
  // 5,6) Check what energy is present in both L diagrams //  // > CustomCode.answerAssistants:189
  //////////////////////////////////////////////////////////  // > CustomCode.answerAssistants:190
  function check5n6assistant(C,E,G,I,K,N,energyLst,stateWord){  // > CustomCode.answerAssistants:191
    // works similarly to zeroExceptEnergy() where it checks arguments for FALSE  // > CustomCode.answerAssistants:192
    // C is either (iniC) or (finC), which give T or F → same goes for the other variables  // > CustomCode.answerAssistants:193
    // energyLst - [iniTotalEnergy] or [finTotalEnergy]  // > CustomCode.answerAssistants:194
    // stateWord - "initial" or "final" strings to put in the hint  // > CustomCode.answerAssistants:195
    ///////////////////////////////////////////////////////////////////////////////////////  // > CustomCode.answerAssistants:196
      // > CustomCode.answerAssistants:197
    // Setting up: //  // > CustomCode.answerAssistants:198
    let checkLst = [C,E,G,I,K,N]    // lst contains T / F  // > CustomCode.answerAssistants:199
    let wordings = ["Chemical","Elastic","Gravitational","Internal","Kinetic","Nuclear"]  // > CustomCode.answerAssistants:200
      // > CustomCode.answerAssistants:201
    // checking process: //  // > CustomCode.answerAssistants:202
    for (let i=0; i< energyLst.length; i++){  // > CustomCode.answerAssistants:203
      if ( (checkLst[i] ==false) && ( energyLst[i] !=0) && (!ignoreEnergyLst.includes(i)) ){  // > CustomCode.answerAssistants:204
        // Hint to wrong energy stored //  // > CustomCode.answerAssistants:205
        hint = ""  // > CustomCode.answerAssistants:206
        for (let wordID=0; wordID < wordings.length; wordID++){  // > CustomCode.answerAssistants:207
          if (i==wordID){hint += wordings[wordID]}  // > CustomCode.answerAssistants:208
          }  // > CustomCode.answerAssistants:209
        hint += " energy should NOT be\nstored in the "+stateWord+" state of the system."  // > CustomCode.answerAssistants:210
        return false  // > CustomCode.answerAssistants:211
        }  // > CustomCode.answerAssistants:212
      else if ( (checkLst[i] ==true) && (energyLst[i] ==0) ){  // > CustomCode.answerAssistants:213
        // Hint to store correct energy //  // > CustomCode.answerAssistants:214
        hint = ""  // > CustomCode.answerAssistants:215
        for (let wordID=0; wordID < wordings.length; wordID++){  // > CustomCode.answerAssistants:216
          if (i==wordID){hint += wordings[wordID]}  // > CustomCode.answerAssistants:217
          }  // > CustomCode.answerAssistants:218
        hint += " energy should be\nstored in the "+stateWord+" state of the system."  // > CustomCode.answerAssistants:219
        return false  // > CustomCode.answerAssistants:220
        }  // > CustomCode.answerAssistants:221
      }  // > CustomCode.answerAssistants:222
    return true  // > CustomCode.answerAssistants:223
    }  // > CustomCode.answerAssistants:224
      // > CustomCode.answerAssistants:225
  //////////////////////////////////////////////////////////  // > CustomCode.answerAssistants:226
  // 7) Check the amount of energy with the formula given //  // > CustomCode.answerAssistants:227
  //////////////////////////////////////////////////////////  // > CustomCode.answerAssistants:228
  function check7assistant(){  // > CustomCode.answerAssistants:229
    let wordings = ["chemical","elastic","gravitational potential","internal","kinetic","nuclear"]  // > CustomCode.answerAssistants:230
    // load formula from userCode //  // > CustomCode.answerAssistants:231
    finalC=999; finalE=999; finalG=999; finalI=999; finalK=999; finalN=999; // to check whether user edited var  // > CustomCode.answerAssistants:232
    inequalityCheckLst = []  // final judgement  // > CustomCode.answerAssistants:233
    runUserCode("Error in code, please review code again.");  // > CustomCode.answerAssistants:234
    // checking process: //  // > CustomCode.answerAssistants:235
    passfail = []; // final judgement  // > CustomCode.answerAssistants:236
    let finalLst = [finalC, finalE, finalG, finalI, finalK, finalN];  // > CustomCode.answerAssistants:237
    //let finalLst = [fC,fE, fG, fI, fK, fN]; // = this is finTotalEnergy  // > CustomCode.answerAssistants:238
    let checkLst = [finC,finE,finG,finI,finK,finN];    // lst contains T/F  // > CustomCode.answerAssistants:239
    debuggg = finalLst+"\ncheckLst: "+checkLst+"\ninequalityCheckLst: "+inequalityCheckLst;  // > CustomCode.answerAssistants:240
    // check for the correct energy present in the initial state before checking condition //   // > CustomCode.answerAssistants:241
    for (let i=0; i < finTotalEnergy.length ; i++){  // > CustomCode.answerAssistants:242
      if ( checkLst[i] ==true && finalLst[i]!=999 ) {  // > CustomCode.answerAssistants:243
        if (finalLst[i] == finTotalEnergy[i]) {  // > CustomCode.answerAssistants:244
          passfail += true  // > CustomCode.answerAssistants:245
          }  // > CustomCode.answerAssistants:246
        else{  // > CustomCode.answerAssistants:247
          //alert("wrong")  // > CustomCode.answerAssistants:248
          hint = "The amount of "+wordings[i]+" energy in the final state is wrong"  // > CustomCode.answerAssistants:249
          passfail += false  // > CustomCode.answerAssistants:250
          }  // > CustomCode.answerAssistants:251
        }  // > CustomCode.answerAssistants:252
      }  // > CustomCode.answerAssistants:253
    // Final judgement: //  // > CustomCode.answerAssistants:254
    debuggg += "\npassfail: "+passfail;  // Equality formulas  // > CustomCode.answerAssistants:255
    if ( !inequalityCheckLst.includes(false) ){  // check inequality formula(s) if any  // > CustomCode.answerAssistants:256
      if ( allFalseLst(checkLst) ){  // highly unlikely this will occur  // > CustomCode.answerAssistants:257
        hint = "There should be no energy\npresent in the FINAL state.";  // > CustomCode.answerAssistants:258
        return false  // > CustomCode.answerAssistants:259
        }  // > CustomCode.answerAssistants:260
      if ( !passfail.includes(false) ){return true}  // check equality formula(s) if any  // > CustomCode.answerAssistants:261
      if ( passfail.includes(false) ){return false}   // > CustomCode.answerAssistants:262
      return true    // > CustomCode.answerAssistants:263
      }  // > CustomCode.answerAssistants:264
    else if ( inequalityCheckLst.includes(false) ){  // > CustomCode.answerAssistants:265
      hint = "The amount of energy in the final state is wrong.";  // > CustomCode.answerAssistants:266
      return false  // > CustomCode.answerAssistants:267
      }  // > CustomCode.answerAssistants:268
    }  // > CustomCode.answerAssistants:269

  //////////////////////////////////////////////////  // > CustomCode.check4assistant:1
  // 4) Check what energy is being transfered OUT //  // > CustomCode.check4assistant:2
  //////////////////////////////////////////////////  // > CustomCode.check4assistant:3
  function check4assistant(){  // > CustomCode.check4assistant:4
    if (check4b){    // → confirm 2 types of energy are transferred  // > CustomCode.check4assistant:5
      if (check4b && (EtransOUT >= 0 && EtransOUT2 >= 0) ){  // > CustomCode.check4assistant:6
          if ((EtransOUT > 0 && updateTransOUT == 0) || (EtransOUT2 > 0 && updateTransOUT2 == 0)) {  // > CustomCode.check4assistant:7
            hint = "Unspecified energy cannot have a value of more than 0.";  // > CustomCode.check4assistant:8
            return false  // > CustomCode.check4assistant:9
          }  // > CustomCode.check4assistant:10
        if ((updateTransOUT == 0 && check4aEnergy == "") ||  // > CustomCode.check4assistant:11
            (updateTransOUT == 1 && check4aEnergy == "through propagation of waves") ||   // > CustomCode.check4assistant:12
            (updateTransOUT == 2 && check4aEnergy == "mechanically") ||   // > CustomCode.check4assistant:13
            (updateTransOUT == 3 && check4aEnergy == "through heating") ||   // > CustomCode.check4assistant:14
            (updateTransOUT == 4 && check4aEnergy == "electrically") ||  // > CustomCode.check4assistant:15
            (updateTransOUT == 5 && check4aEnergy == "chemically") ){  // > CustomCode.check4assistant:16
          if (updateTransOUT2 == 0 && check4bEnergy == ""){return true}  // > CustomCode.check4assistant:17
          else if (updateTransOUT2 == 1 && check4bEnergy == "through propagation of waves"){return true}  // > CustomCode.check4assistant:18
          else if (updateTransOUT2 == 2 && check4bEnergy == "mechanically"){return true}  // > CustomCode.check4assistant:19
          else if (updateTransOUT2 == 3 && check4bEnergy == "through heating"){return true}  // > CustomCode.check4assistant:20
          else if (updateTransOUT2 == 4 && check4bEnergy == "electrically"){return true}  // > CustomCode.check4assistant:21
          else if (updateTransOUT2 == 5 && check4bEnergy == "chemically"){return true}  // > CustomCode.check4assistant:22
          else{  // > CustomCode.check4assistant:23
            hint = "There should be some energy transferred out\nof the system "+check4bEnergy+" due to \n"+check4bReason;  // > CustomCode.check4assistant:24
            return false  // > CustomCode.check4assistant:25
            }  // > CustomCode.check4assistant:26
          }  // > CustomCode.check4assistant:27
        else if ((updateTransOUT2 == 0 && check4aEnergy == "") ||  // > CustomCode.check4assistant:28
            (updateTransOUT2 == 1 && check4aEnergy == "through propagation of waves") ||   // > CustomCode.check4assistant:29
            (updateTransOUT2 == 2 && check4aEnergy == "mechanically") ||   // > CustomCode.check4assistant:30
            (updateTransOUT2 == 3 && check4aEnergy == "through heating") ||    // > CustomCode.check4assistant:31
            (updateTransOUT2 == 4 && check4aEnergy == "electrically") ||  // > CustomCode.check4assistant:32
            (updateTransOUT2 == 5 && check4aEnergy == "chemically") ){  // > CustomCode.check4assistant:33
          if (updateTransOUT == 0 && check4bEnergy == ""){return true}  // > CustomCode.check4assistant:34
          else if (updateTransOUT == 1 && check4bEnergy == "through propagation of waves"){return true}  // > CustomCode.check4assistant:35
          else if (updateTransOUT == 2 && check4bEnergy == "mechanically"){return true}  // > CustomCode.check4assistant:36
          else if (updateTransOUT == 3 && check4bEnergy == "through heating"){return true}  // > CustomCode.check4assistant:37
          else if (updateTransOUT == 4 && check4bEnergy == "electrically"){return true}  // > CustomCode.check4assistant:38
          else if (updateTransOUT == 5 && check4bEnergy == "chemically"){return true}  // > CustomCode.check4assistant:39
          else{  // > CustomCode.check4assistant:40
            hint = "There should be some energy transferred\nout of the system "+check4bEnergy+" due to \n"+check4bReason;  // > CustomCode.check4assistant:41
            return false  // > CustomCode.check4assistant:42
            }  // > CustomCode.check4assistant:43
          }  // > CustomCode.check4assistant:44
        else{  // > CustomCode.check4assistant:45
          hint = "There should be some energy transferred\nout of the system "+check4aEnergy+" due to \n"+check4aReason;  // > CustomCode.check4assistant:46
          return false  // > CustomCode.check4assistant:47
          }  // > CustomCode.check4assistant:48
        }  // > CustomCode.check4assistant:49
      else{  // > CustomCode.check4assistant:50
        hint = "There should have some energy\ntransferred out of the system\n"+check4aEnergy+" and "+check4bEnergy+".";  // > CustomCode.check4assistant:51
        }  // > CustomCode.check4assistant:52
      }  // > CustomCode.check4assistant:53
    else if (check4a){  // > CustomCode.check4assistant:54
      if ((EtransOUT > 0 && updateTransOUT == 0)) {  // > CustomCode.check4assistant:55
          hint = "Unspecified energy cannot have a value of more than 0.";  // > CustomCode.check4assistant:56
          return false  // > CustomCode.check4assistant:57
      }  // > CustomCode.check4assistant:58
      if (EtransOUT >= 0 && EtransOUT2 ==0){  // > CustomCode.check4assistant:59
        if (updateTransOUT == 0 && check4aEnergy == ""){return true}  // > CustomCode.check4assistant:60
        if (updateTransOUT == 1 && check4aEnergy == "through propagation of waves"){return true}  // > CustomCode.check4assistant:61
        if (updateTransOUT == 2 && check4aEnergy == "mechanically"){return true}  // > CustomCode.check4assistant:62
        if (updateTransOUT == 3 && check4aEnergy == "through heating"){return true}  // > CustomCode.check4assistant:63
        if (updateTransOUT == 4 && check4aEnergy == "electrically"){return true}  // > CustomCode.check4assistant:64
        if (updateTransOUT == 5 && check4aEnergy == "chemically"){return true}  // > CustomCode.check4assistant:65
        }  // > CustomCode.check4assistant:66
      else if (EtransOUT ==0 && EtransOUT2 >= 0){  // > CustomCode.check4assistant:67
        if (updateTransOUT2 == 0 && check4aEnergy == ""){return true}  // > CustomCode.check4assistant:68
        if (updateTransOUT2 == 1 && check4aEnergy == "through propagation of waves"){return true}  // > CustomCode.check4assistant:69
        if (updateTransOUT2 == 2 && check4aEnergy == "mechanically"){return true}  // > CustomCode.check4assistant:70
        if (updateTransOUT2 == 3 && check4aEnergy == "through heating"){return true}  // > CustomCode.check4assistant:71
        if (updateTransOUT2 == 4 && check4aEnergy == "electrically"){return true}  // > CustomCode.check4assistant:72
        if (updateTransOUT2 == 5 && check4aEnergy == "chemically"){return true}  // > CustomCode.check4assistant:73
        }  // > CustomCode.check4assistant:74
      else if (EtransOUT >= 0 && EtransOUT2 >= 0){  // > CustomCode.check4assistant:75
        if (updateTransOUT == 0 && updateTransOUT2 == 0 && check4aEnergy == ""){return true}  // > CustomCode.check4assistant:76
        if (updateTransOUT == 1 && updateTransOUT2 == 1 && check4aEnergy == "through propagation of waves"){return true}  // > CustomCode.check4assistant:77
        if (updateTransOUT == 2 && updateTransOUT2 == 2 && check4aEnergy == "mechanically"){return true}  // > CustomCode.check4assistant:78
        if (updateTransOUT == 3 && updateTransOUT2 == 3 && check4aEnergy == "through heating"){return true}  // > CustomCode.check4assistant:79
        if (updateTransOUT == 4 && updateTransOUT2 == 4 && check4aEnergy == "electrically"){return true}  // > CustomCode.check4assistant:80
        if (updateTransOUT == 5 && updateTransOUT2 == 5 && check4aEnergy == "chemically"){return true}  // > CustomCode.check4assistant:81
        hint = "There should only be some energy transferred\nout of the system "+ check4aEnergy+".";  // > CustomCode.check4assistant:82
        return false  // > CustomCode.check4assistant:83
        }  // > CustomCode.check4assistant:84
      hint = "There should be some energy transferred\nout of the system "+check4aEnergy+" due to \n"+check4aReason;  // > CustomCode.check4assistant:85
      return false  // > CustomCode.check4assistant:86
      }  // > CustomCode.check4assistant:87
    else if (check4a ==false && check4b ==false){  // > CustomCode.check4assistant:88
      if (EtransOUT ==0 && EtransOUT2 ==0){return true}  // > CustomCode.check4assistant:89
      else{  // > CustomCode.check4assistant:90
        hint = "The energy transferred out\nof the system should be zero.";  // > CustomCode.check4assistant:91
        return false  // > CustomCode.check4assistant:92
        }  // > CustomCode.check4assistant:93
      }  // > CustomCode.check4assistant:94
    else{  // > CustomCode.check4assistant:95
      debuggg="smth wrong at check4 :( ";  // > CustomCode.check4assistant:96
      return true  // > CustomCode.check4assistant:97
      }  // > CustomCode.check4assistant:98
    }  // > CustomCode.check4assistant:99

  //https://developer.mozilla.org/en-US/docs/Web/Guide/API/DOM/Using_full_screen_mode  // > CustomCode.fullscreen:1
  // does not work for iOS   // > CustomCode.fullscreen:2
  /*jslint browser:true */  // > CustomCode.fullscreen:3
  function toggleFullScreen() {  // > CustomCode.fullscreen:4
    if (!document.fullscreenElement &&    // alternative standard method  // > CustomCode.fullscreen:5
        !document.mozFullScreenElement && !document.webkitFullscreenElement && !document.msFullscreenElement ) {  // current working methods  // > CustomCode.fullscreen:6
      if (document.documentElement.requestFullscreen) {  // > CustomCode.fullscreen:7
        document.documentElement.requestFullscreen();  // > CustomCode.fullscreen:8
      } else if (document.documentElement.msRequestFullscreen) {  // > CustomCode.fullscreen:9
        document.documentElement.msRequestFullscreen();  // > CustomCode.fullscreen:10
      } else if (document.documentElement.mozRequestFullScreen) {  // > CustomCode.fullscreen:11
        document.documentElement.mozRequestFullScreen();  // > CustomCode.fullscreen:12
      } else if (document.documentElement.webkitRequestFullscreen) {  // > CustomCode.fullscreen:13
        document.documentElement.webkitRequestFullscreen();  // > CustomCode.fullscreen:14
      }  // > CustomCode.fullscreen:15
    } else {  // > CustomCode.fullscreen:16
      if (document.exitFullscreen) {  // > CustomCode.fullscreen:17
        document.exitFullscreen();  // > CustomCode.fullscreen:18
      } else if (document.msExitFullscreen) {  // > CustomCode.fullscreen:19
        document.msExitFullscreen();  // > CustomCode.fullscreen:20
      } else if (document.mozCancelFullScreen) {  // > CustomCode.fullscreen:21
        document.mozCancelFullScreen();  // > CustomCode.fullscreen:22
      } else if (document.webkitExitFullscreen) {  // > CustomCode.fullscreen:23
        document.webkitExitFullscreen();  // > CustomCode.fullscreen:24
      }  // > CustomCode.fullscreen:25
    }  // > CustomCode.fullscreen:26
  }  // > CustomCode.fullscreen:27

  // code to be copied to EJSS source code under Custom and used in drawingPanel3D and plottingPanel2D  // > CustomCode.changeOrientation:1
  // address the problem is height difference is iOS app , epub, and Firefox  // > CustomCode.changeOrientation:2
  // user need to change only k and kepub  // > CustomCode.changeOrientation:3
  // copy %changeOrientation()% into the Height Field of drawingPanel3D and plottingPanel2D  // > CustomCode.changeOrientation:4
  function changeOrientation() {  // > CustomCode.changeOrientation:5
     // > CustomCode.changeOrientation:6
  var k =0.90 ; // k control height 1 is for full screen, 0.9 shorten etc  // > CustomCode.changeOrientation:7
  var kapple =0.90 // control apple app height  // > CustomCode.changeOrientation:8
  var kepub =0.90 ;  // > CustomCode.changeOrientation:9
  // check platform for Apps  // > CustomCode.changeOrientation:10
  try { // allow code to run in Student Learning Space   // > CustomCode.changeOrientation:11
    var iOSapp =  (typeof parent.device != 'undefined' && parent.device.platform == "iOS");  // > CustomCode.changeOrientation:12
    var Androidapp = (typeof parent.device != 'undefined' && parent.device.platform == "Android");  // > CustomCode.changeOrientation:13
  } catch(e) {  // > CustomCode.changeOrientation:14
    var iOSapp = false;  // > CustomCode.changeOrientation:15
    var Androidapp = false;  // > CustomCode.changeOrientation:16
  }  // > CustomCode.changeOrientation:17
  // check platform for web browsers  // > CustomCode.changeOrientation:18
  var iOS =/iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;  // > CustomCode.changeOrientation:19
  var iPad =/iPad/.test(navigator.userAgent) && !window.MSStream;  // > CustomCode.changeOrientation:20
  var iPhone = /iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;  // > CustomCode.changeOrientation:21
  var Android= /Android|android/i.test(navigator.userAgent);  // > CustomCode.changeOrientation:22
  //navigator  // > CustomCode.changeOrientation:23
  var Firefox = navigator.userAgent.indexOf("Firefox") != -1;  // > CustomCode.changeOrientation:24
     // > CustomCode.changeOrientation:25
  switch (window.orientation) { // using window.orientation as deciding factor  // > CustomCode.changeOrientation:26
    case 0:  // > CustomCode.changeOrientation:27
    case 180:  // > CustomCode.changeOrientation:28
      this.screenOrientation = 'portrait';  // > CustomCode.changeOrientation:29
      if (iOSapp){ // does not seems to work  // > CustomCode.changeOrientation:30
          // > CustomCode.changeOrientation:31
        return window.screen.height*kapple;  //0.1 for app and 0.1 for nonfullscreenapp    // > CustomCode.changeOrientation:32
        // > CustomCode.changeOrientation:33
      }  // > CustomCode.changeOrientation:34
      else if (_isEPub){ // does not seems to work  // > CustomCode.changeOrientation:35
        //   return Math.max(window.screen.width,window.screen.height)*0.9;  // > CustomCode.changeOrientation:36
        return window.innerHeight*kepub;  //0.1 for app and 0.1 for nonfullscreenapp    // > CustomCode.changeOrientation:37
        // return window.screen.height;  // > CustomCode.changeOrientation:38
        //  return window.innerHeight;  // > CustomCode.changeOrientation:39
        // return document.documentElement.clientHeight;  // > CustomCode.changeOrientation:40
      }  // > CustomCode.changeOrientation:41
       // > CustomCode.changeOrientation:42
      else {  // > CustomCode.changeOrientation:43
         // > CustomCode.changeOrientation:44
        return 100*k+"vh";  // > CustomCode.changeOrientation:45
      }  // > CustomCode.changeOrientation:46
      break;  // > CustomCode.changeOrientation:47
    case 90:  // > CustomCode.changeOrientation:48
    case -90:  // > CustomCode.changeOrientation:49
      this.screenOrientation = 'landscape';  // > CustomCode.changeOrientation:50
     // > CustomCode.changeOrientation:51
      if (iOSapp){ // App  // > CustomCode.changeOrientation:52
        return window.screen.width*kapple;    // > CustomCode.changeOrientation:53
        // return window.screen.height;  // > CustomCode.changeOrientation:54
        //  return window.innerHeight;  // > CustomCode.changeOrientation:55
        //  return document.documentElement.clientHeight;  // > CustomCode.changeOrientation:56
      }  // > CustomCode.changeOrientation:57
      else if (_isEPub){ // does not seems to work  // > CustomCode.changeOrientation:58
        //   return Math.max(window.screen.width,window.screen.height)*0.9;  // > CustomCode.changeOrientation:59
        return window.innerHeight*kepub;  //0.1 for app and 0.1 for nonfullscreenapp    // > CustomCode.changeOrientation:60
        // return window.screen.height;  // > CustomCode.changeOrientation:61
        //  return window.innerHeight;  // > CustomCode.changeOrientation:62
        // return document.documentElement.clientHeight;  // > CustomCode.changeOrientation:63
      }  // > CustomCode.changeOrientation:64
       // > CustomCode.changeOrientation:65
      else {  // > CustomCode.changeOrientation:66
        return 100*k+"vh";  // > CustomCode.changeOrientation:67
        }  // > CustomCode.changeOrientation:68
      break;  // > CustomCode.changeOrientation:69
    default:  // > CustomCode.changeOrientation:70
      this.screenOrientation = 'unknown';  // > CustomCode.changeOrientation:71
      //       return (iPad)?""+(window.screen.width+window.screen.height)*0.4:((iPhone)?""+window.screen.width:_view._format(window.innerHeight*0.9,"0"));  // > CustomCode.changeOrientation:72
       if (Firefox){  // > CustomCode.changeOrientation:73
        return window.innerHeight*k;// number as of 20180831 Firefox does not support vh yet so need a separate line to handle  // > CustomCode.changeOrientation:74
        }  // > CustomCode.changeOrientation:75
     //   else if (iOS&&(window.orientation==0)||(window.orientation==180)){  // > CustomCode.changeOrientation:76
     //   return  window.screen.height*k;// number as of 20180831 Firefox does not support vh yet so need a separate line to handle  // > CustomCode.changeOrientation:77
     //   }  // > CustomCode.changeOrientation:78
      //  else if (iOS&&(window.orientation==90)||(window.orientation==-90)){  // > CustomCode.changeOrientation:79
     //   return  window.screen.width*k;// number as of 20180831 Firefox does not support vh yet so need a separate line to handle  // > CustomCode.changeOrientation:80
     //   }  // > CustomCode.changeOrientation:81
        else {  // > CustomCode.changeOrientation:82
        //alert();  // > CustomCode.changeOrientation:83
        // return 100*k+"%"; // work on fullscreen works in EJSS6.0beta  // > CustomCode.changeOrientation:84
          //  works in EjsS_5.3_180131  // > CustomCode.changeOrientation:85
        return  window.innerHeight*k; // work on panel   // > CustomCode.changeOrientation:86
           // > CustomCode.changeOrientation:87
  }  // > CustomCode.changeOrientation:88
  }  // > CustomCode.changeOrientation:89
     // > CustomCode.changeOrientation:90
  }  // > CustomCode.changeOrientation:91

